WITH valid_departments AS (SELECT * FROM departments WHERE dept_name <> 'Finance' AND dept_name <> 'Legal'), departments_stats AS (SELECT location, CASE WHEN budget >= 3395000 THEN 'high' WHEN budget >= 818000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(CASE WHEN location = 'Singapore' THEN 1 END) AS singapore_count, MAX(budget) - MIN(budget) AS budget_range FROM valid_departments GROUP BY location, CASE WHEN budget >= 3395000 THEN 'high' WHEN budget >= 818000 THEN 'mid' ELSE 'low' END) SELECT location, budget_bucket, singapore_count, budget_range FROM departments_stats WHERE budget_range > 45
